// How do I deserialize saved color data back into usable color objects in a document?

// Round-trip colors through JSON to verify that each restored value matches the original in a document.

const doc = Api.GetDocument();
const paragraph = doc.GetElement(0);

const colors = [
	Api.RGB(93, 192, 232),
	Api.RGBA(149, 192, 56, 128),
	Api.HexColor('#FF6F3D'),
	Api.ThemeColor('accent2'),
	Api.AutoColor()
];

for (let i = 0; i < colors.length; i++) {
	const original = colors[i];
	const json = JSON.parse(original.ToJSON());
	const restored = original.FromJSON(json);

	if (i > 0) paragraph.AddLineBreak();
	let run = Api.CreateRun();
	run.SetColor(original);
	run.AddText('Original: ' + original.GetHex());
	paragraph.Push(run);

	run = Api.CreateRun();
	run.AddText(' - ');
	paragraph.Push(run);

	run = Api.CreateRun();
	run.SetColor(restored);
	run.AddText('Restored: ' + restored.GetHex());
	paragraph.Push(run);
}

// How do I identify what kind of color object is used in a document?

// Useful when you need to confirm the object type before processing color properties.

const doc = Api.GetDocument();
const color = Api.ThemeColor('accent1');
const paragraph = doc.GetElement(0);
paragraph.AddText('Class type of ApiColor instance: ' + color.GetClassType());

// How do I get the hexadecimal representation of a color in a document?

// Verify that theme and auto colors always return black hex while hex-defined colors return their actual value.

const doc = Api.GetDocument();

const themeColor = Api.ThemeColor('accent1');
const autoColor = Api.AutoColor();
const rgbaColor = Api.HexColor('#FF0000');

const themeColorHex = themeColor.GetHex();
const autoColorHex = autoColor.GetHex();
const rgbaColorHex = rgbaColor.GetHex();

const paragraph = doc.GetElement(0);
paragraph.AddText('Hex of themeColor: ' + themeColorHex);
paragraph.AddLineBreak();
paragraph.AddText('Hex of autoColor: ' + autoColorHex);
paragraph.AddLineBreak();
paragraph.AddText('Hex of rgbaColor: ' + rgbaColorHex);
paragraph.AddLineBreak();
paragraph.AddText('Hex for theme colors and auto color are always opaque black; actual color depends on the document theme.');

// How do I read the individual RGB components of a color in a document?

// Compare channel values across theme, auto, and hex colors to understand how each type resolves in a document.

const doc = Api.GetDocument();

const themeColor = Api.ThemeColor('accent1');
const autoColor = Api.AutoColor();
const hexColor = Api.HexColor('#FF0000');

const themeColorRGB = themeColor.GetRGB();
const autoColorRGB = autoColor.GetRGB();
const hexColorRGB = hexColor.GetRGB();

const paragraph = doc.GetElement(0);
paragraph.AddText('RGB of themeColor: ' + themeColorRGB.r + ', ' + themeColorRGB.g + ', ' + themeColorRGB.b);
paragraph.AddLineBreak();
paragraph.AddText('RGB of autoColor: ' + autoColorRGB.r + ', ' + autoColorRGB.g + ', ' + autoColorRGB.b);
paragraph.AddLineBreak();
paragraph.AddText('RGB of hexColor: ' + hexColorRGB.r + ', ' + hexColorRGB.g + ', ' + hexColorRGB.b);
paragraph.AddLineBreak();
paragraph.AddText('RGB for theme colors and auto color are always opaque black; actual color depends on the document theme.');

// How do I read the RGBA components of a color in a document?

